using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task ClassInit(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.DisposeAsync();
        await _appHost.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
        Assert.IsTrue(
            response.Messages.Any(m => m.Text?.Contains("Paris", StringComparison.OrdinalIgnoreCase) == true),
            "Expected the response to mention Paris.");
    }

    [TestMethod]
    public async Task Chat_EvaluateResponseQuality()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync("ChatQuality");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain photosynthesis in two sentences.")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);

        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var evalResponse = response.Messages
            .Where(m => m.Role == ChatRole.Assistant)
            .Select(m => m.Text ?? string.Empty)
            .FirstOrDefault() ?? string.Empty;

        await scenario.EvaluateAsync(
            messages,
            new ChatMessage(ChatRole.Assistant, evalResponse),
            evaluators);
    }

    [TestMethod]
    public async Task Chat_HandlesMultiTurnConversation()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Remember the number 42."),
        };

        var response1 = await _chatClient.GetResponseAsync(messages);
        Assert.IsNotNull(response1);

        messages.AddRange(response1.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "What number did I ask you to remember?"));

        var response2 = await _chatClient.GetResponseAsync(messages);
        Assert.IsNotNull(response2);
        Assert.IsTrue(
            response2.Messages.Any(m => m.Text?.Contains("42") == true),
            "Expected the model to recall the number 42.");
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "evaluation-results");

        return DiskBasedReportingConfiguration.Create(storageRootPath: path);
    }
}
